const RolloverDueBoundedSuccessors = `-- name: RolloverDueBoundedSuccessors :many
UPDATE assertion
SET status = 'superseded',
    closure_reason = 'superseded',
    knowledge_to = GREATEST($1::timestamptz, knowledge_from)
WHERE status = 'accepted'
  AND knowledge_to IS NULL
  AND superseded_by IS NOT NULL
  AND valid_to IS NOT NULL
  AND valid_to <= $1
RETURNING id, subject_node_id, predicate_key, object_node_id, value_text, value_num, value_date, value_bool, valid_from, valid_to, knowledge_from, knowledge_to, confidence, salience, status, closure_reason, superseded_by, trust_tier, proposition_key, created_at
`

// The rollover job: terminalize the bounded-with-pending-successor rows whose
// bound has been reached. Scoped TIGHT — superseded_by IS NOT NULL excludes
// successor-less historical accepted facts (which simply aren't current). Sets
// status='superseded', closure_reason='superseded'. knowledge_to is
// GREATEST(now, knowledge_from) so a row whose knowledge_from was set in the
// future via a KnowledgeFromOverride does not violate the assertion_knowledge_range
// CHECK and abort the whole sweep. Returns the updated rows so the caller can emit
// one assertion.superseded event per row.
func (q *Queries) RolloverDueBoundedSuccessors(ctx context.Context, now time.Time) ([]*Assertion, error) {
	rows, err := q.db.Query(ctx, RolloverDueBoundedSuccessors, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*Assertion{}
	for rows.Next() {
		var i Assertion
		if err := rows.Scan(
			&i.ID,
			&i.SubjectNodeID,
			&i.PredicateKey,
			&i.ObjectNodeID,
			&i.ValueText,
			&i.ValueNum,
			&i.ValueDate,
			&i.ValueBool,
			&i.ValidFrom,
			&i.ValidTo,
			&i.KnowledgeFrom,
			&i.KnowledgeTo,
			&i.Confidence,
			&i.Salience,
			&i.Status,
			&i.ClosureReason,
			&i.SupersededBy,
			&i.TrustTier,
			&i.PropositionKey,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const SetAssertionPendingSuccessor = `-- name: SetAssertionPendingSuccessor :exec
UPDATE assertion
SET superseded_by = $1
WHERE id = $2
`

type SetAssertionPendingSuccessorParams struct {
	SupersededBy *uuid.UUID `json:"superseded_by"`
	ID           uuid.UUID  `json:"id"`
}

// Widen-merge linkage inheritance: when a same-value merge absorbs a stint
// bounded by a pending future successor into a survivor that has none, the
// survivor takes over the predecessor role (superseded_by while still
// accepted) so the rollover sweep terminalizes it at the bound and emits the
// assertion.superseded event the derived caches rely on.
func (q *Queries) SetAssertionPendingSuccessor(ctx context.Context, arg SetAssertionPendingSuccessorParams) error {
	_, err := q.db.Exec(ctx, SetAssertionPendingSuccessor, arg.SupersededBy, arg.ID)
	return err
}

